    const x = open.find((y) => y.period === v.period); const a = v.amount === '' || v.amount === null || v.amount === undefined ? x.left : E.r2(v.amount); if (!(a > 0) || a > x.left) return toast(`Tutar 0 ile ${money(x.left)} arasında olmalı`, 'err');
    const pay = { period: x.period, paid: true, amount: a, type: v.type, at: new Date().toISOString(), by: me() }; l.payments = [...(l.payments || []), pay]; db.log('Kira tahsilatı', `${l.tenant} · ${x.period} · ${money(a)}`); db.save(); toast('Tahsilat kaydedildi', 'ok');
