    const dep = Number(l.deposit) || 0, ret = E.r2(v.refund); if (ret < 0 || ret > dep) return toast(`İade 0 ile ${money(dep)} arasında olmalı`, 'err'); if (ret < dep && !String(v.note || '').trim()) return toast('Kesinti gerekçesi yazın', 'err');
