      if (a === 'inv') { if (d.invoice && !d.invoice.test && !(await confirm(`${d.invoice.no} kesilmiş. Yeniden kesilsin mi?`))) return; const vat = Number(S().vatPct) || 0; const r = await NS.ebelge.create({ docType: 'auto', no: `H${String(d.id).replace(/\W/g, '').slice(0, 12)}`, buyer: d.buyer, note: `${prop(d.prop).title} aracılık hizmeti`, lines: [{ name: `Aracılık hizmet bedeli · ${prop(d.prop).no || ''}`, qty: 1, unit: 'adet', price: commission(d), disc: 0, vat }] }); if (r && r.ok) { d.invoice = { id: r.id, no: r.no, type: r.type, date: today(), ...(r.simulated ? { test: true } : {}) }; db.log('Fatura', `${d.buyer} · ${r.no}${r.simulated ? ' · TEST' : ''}`); db.save(); app.refresh(); } return; }
